import{_ as e,c as t,o as i,Q as p}from"./chunks/framework.5f28ab71.js";const E=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"runtime/h/index.md","lastUpdated":1724226267000}'),o={name:"runtime/h/index.md"},n=p("<p>我们知道 h 函数核心是用来:创建 vnode 的。但是对于 vnode 而言，它存在很多种不同的节点类型。 查看 <code>packages/runtime-core/src/renderer.ts</code> 中第 354 行 patch 方法的代码可知， Vue 总共处理 了:</p><ol><li><p>Text :文本节点</p></li><li><p>Comment :注释节点</p></li><li><p>Static :静态 DOM 节点</p></li><li><p>Fragment :包含多个根节点的模板被表示为一个片段 (fragment) 5. ELEMENT : DOM 节点</p></li><li><p>COMPONENT :组件</p></li><li><p>TELEPORT :新的 内置组件</p></li><li><p>SUSPENSE :新的 内置组件</p></li><li><p>...</p></li></ol><p>各种不同类型的节点，而每一种类型的处理都对应着不同的 VNode 。所以就需要把各种类型的 VNode 构建出来(不会全部处理所有类型，只会选择比较有代表性的部分)，以便，后面进行 render 渲染。</p>",3),r=[n];function a(l,_,c,d,s,m){return i(),t("div",null,r)}const h=e(o,[["render",a]]);export{E as __pageData,h as default};
